#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        int n;        cin >> n;        vector<ll>a(n);        ll sum = 0;        for(auto &x : a){            cin >> x;            sum += x;        }                if(sum % 2 == 0){            cout << "Yes" << endl;        }else{            cout << "No" << endl;        }     }     return 0;}